    tree := CASE (e->>'doc_type') || ':' || (e->>'agency') || ':' || (e->>'version')
    WHEN 'pas:fda:fda-pas-lifecycle-v1.2' THEN $pack$[{"key":"PAS-COVER","parent_key":null,"label":"Cover Letter","mandatory":true,"path_order":1},{"key":"PAS-356H","parent_key":null,"label":"Form FDA 356h","mandatory":true,"path_order":2},{"key":"PAS-SUMMARY","parent_key":null,"label":"Summary and Description of the Change","mandatory":true,"path_order":3},{"key":"PAS-LABELING","parent_key":null,"label":"Labeling (Annotated and Clean)","mandatory":false,"path_order":4},{"key":"PAS-CLINICAL","parent_key":null,"label":"Clinical and Nonclinical Data (Efficacy Supplement)","mandatory":false,"path_order":5},{"key":"PAS-PEDIATRIC","parent_key":null,"label":"Pediatric Assessment, or Waiver or Deferral Request (PREA)","mandatory":false,"path_order":6},{"key":"PAS-PATENT","parent_key":null,"label":"Patent Information and Exclusivity Claim (Changed Formulation, Indication or Strength)","mandatory":false,"path_order":7},{"key":"PAS-ENV","parent_key":null,"label":"Environmental Assessment or Categorical Exclusion Claim","mandatory":true,"path_order":8},{"key":"PAS-FEE","parent_key":null,"label":"User Fee Determination and Field Copy Certification","mandatory":false,"path_order":9},{"key":"CTD","parent_key":null,"label":"Updated CTD Sections","mandatory":false,"path_order":10},{"key":"2.3","parent_key":"CTD","label":"Quality Overall Summary (QOS)","mandatory":false,"path_order":11},{"key":"2.4","parent_key":"CTD","label":"Nonclinical Overview","mandatory":false,"path_order":12},{"key":"2.5","parent_key":"CTD","label":"Clinical Overview","mandatory":false,"path_order":13},{"key":"2.6","parent_key":"CTD","label":"Nonclinical Written and Tabulated Summaries","mandatory":false,"path_order":14},{"key":"2.7","parent_key":"CTD","label":"Clinical Summary","mandatory":false,"path_order":15},{"key":"3.2.S","parent_key":"CTD","label":"Drug Substance","mandatory":false,"path_order":16},{"key":"3.2.P","parent_key":"CTD","label":"Drug Product","mandatory":false,"path_order":17},{"key":"3.2.A","parent_key":"CTD","label":"Appendices (Facilities and Equipment, Adventitious Agents Safety Evaluation, Excipients)","mandatory":false,"path_order":18},{"key":"3.2.R","parent_key":"CTD","label":"Regional Information","mandatory":false,"path_order":19},{"key":"4.2","parent_key":"CTD","label":"Study Reports","mandatory":false,"path_order":20},{"key":"5.3","parent_key":"CTD","label":"Clinical Study Reports","mandatory":false,"path_order":21}]$pack$::jsonb
    WHEN 'ind_safety_report:fda:fda-ind-safety-report-v1.2' THEN $pack$[{"key":"1","parent_key":null,"label":"IND Safety Report Identification / Route-Dependent Transmittal","mandatory":true,"path_order":1},{"key":"2","parent_key":null,"label":"Individual Case Safety Report (Applicable Case Reporting Route)","mandatory":false,"path_order":2},{"key":"3","parent_key":null,"label":"Causality Assessment (Reasonable Possibility Determination)","mandatory":false,"path_order":3},{"key":"4","parent_key":null,"label":"Expectedness Assessment Against the Investigator Brochure / Protocol","mandatory":false,"path_order":4},{"key":"5","parent_key":null,"label":"Aggregate / Similar-Events and Increased-Rate Analysis","mandatory":false,"path_order":5},{"key":"6","parent_key":null,"label":"Follow-Up Report","mandatory":false,"path_order":6},{"key":"7","parent_key":null,"label":"Previously Submitted Similar Reports and Significance Analysis","mandatory":true,"path_order":7}]$pack$::jsonb
    WHEN 'orphan:fda:fda-orphan-request-v1.2' THEN $pack$[{"key":"1","parent_key":null,"label":"Administrative Information and Sponsor","mandatory":true,"path_order":1},{"key":"2","parent_key":null,"label":"Rare Disease/Condition and Proposed Use","mandatory":true,"path_order":2},{"key":"3","parent_key":null,"label":"Scientific Rationale (Drug Description, Mechanism)","mandatory":true,"path_order":3},{"key":"3.1","parent_key":"3","label":"Clinical Superiority Hypothesis (Same Drug Already Approved for the Same Rare Disease)","mandatory":false,"path_order":4},{"key":"4","parent_key":null,"label":"Prevalence Estimate with Supporting References","mandatory":true,"path_order":5},{"key":"4.1","parent_key":"4","label":"Orphan Subset (Designation for a Subset of Persons with a Disease or Condition)","mandatory":false,"path_order":6},{"key":"5","parent_key":null,"label":"Regulatory Status and Marketing History","mandatory":true,"path_order":7},{"key":"6","parent_key":null,"label":"Scientific Literature and References","mandatory":true,"path_order":8}]$pack$::jsonb
    WHEN 'designation:fda:fda-btd-request-v1.2' THEN $pack$[{"key":"1","parent_key":null,"label":"Cover Letter and Request Statement","mandatory":true,"path_order":1},{"key":"2","parent_key":null,"label":"Product Description and Proposed Indication","mandatory":true,"path_order":2},{"key":"3","parent_key":null,"label":"Serious or Life-Threatening Condition Justification","mandatory":true,"path_order":3},{"key":"5","parent_key":null,"label":"Preliminary Clinical Evidence","mandatory":true,"path_order":4},{"key":"5.1","parent_key":"5","label":"Substantial Improvement over Available Therapy on a Clinically Significant Endpoint","mandatory":true,"path_order":5},{"key":"6","parent_key":null,"label":"Development Plan and Requested Features","mandatory":true,"path_order":6}]$pack$::jsonb
    WHEN 'rmat:fda:fda-rmat-request-v1.1' THEN $pack$[{"key":"1","parent_key":null,"label":"Cover Letter and Request Statement","mandatory":true,"path_order":1},{"key":"2","parent_key":null,"label":"Product Description and Proposed Indication","mandatory":true,"path_order":2},{"key":"2.1","parent_key":"2","label":"Regenerative Medicine Therapy Eligibility","mandatory":true,"path_order":3},{"key":"3","parent_key":null,"label":"Serious or Life-Threatening Condition Justification","mandatory":true,"path_order":4},{"key":"4","parent_key":null,"label":"Potential to Address an Unmet Medical Need","mandatory":true,"path_order":5},{"key":"5","parent_key":null,"label":"Preliminary Clinical Evidence","mandatory":true,"path_order":6},{"key":"6","parent_key":null,"label":"Development Plan and Requested Features","mandatory":true,"path_order":7}]$pack$::jsonb
    WHEN 'icf:ich:c2c-icf-v1.2' THEN $pack$[{"key":"1","parent_key":null,"label":"Study Purpose and Background","mandatory":true,"path_order":1},{"key":"2","parent_key":null,"label":"Study Procedures and Duration","mandatory":true,"path_order":2},{"key":"3","parent_key":null,"label":"Reasonably Foreseeable Risks and Discomforts","mandatory":true,"path_order":3},{"key":"4","parent_key":null,"label":"Expected Benefits","mandatory":true,"path_order":4},{"key":"5","parent_key":null,"label":"Alternatives to Participation","mandatory":true,"path_order":5},{"key":"6","parent_key":null,"label":"Confidentiality of Records","mandatory":true,"path_order":6},{"key":"7","parent_key":null,"label":"Compensation and Treatment for Injury","mandatory":true,"path_order":7},{"key":"8","parent_key":null,"label":"Voluntary Participation and Right to Withdraw","mandatory":true,"path_order":8},{"key":"9","parent_key":null,"label":"Contacts for Questions","mandatory":true,"path_order":9},{"key":"10","parent_key":null,"label":"Signatures (Subject / Legal Representative / Investigator)","mandatory":true,"path_order":10},{"key":"11","parent_key":null,"label":"ClinicalTrials.gov Statement (Applicable Clinical Trials)","mandatory":false,"path_order":11},{"key":"12","parent_key":null,"label":"Additional Elements of Informed Consent (When Appropriate)","mandatory":false,"path_order":12}]$pack$::jsonb
    END;
    SELECT jsonb_array_length(required_sections), required_sections = tree, superseded_by
      INTO n, same, sup
      FROM c2c_rule_packs
     WHERE doc_type = e->>'doc_type' AND agency = e->>'agency' AND version = e->>'version';
    IF NOT FOUND OR n IS DISTINCT FROM (e->>'nodes')::integer OR same IS NOT TRUE THEN
      RAISE EXCEPTION '%:% % must hold this file''s % nodes; found % (tree matches: %)',
        e->>'doc_type', e->>'agency', e->>'version', e->>'nodes',
        coalesce(n::text, 'no row'), coalesce(same::text, 'n/a');
    END IF;
    IF sup IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM c2c_rule_packs
       WHERE doc_type = e->>'doc_type' AND agency = e->>'agency' AND version = sup) THEN
      RAISE EXCEPTION '%:% % is superseded by %, which does not exist',
        e->>'doc_type', e->>'agency', e->>'version', sup;
    END IF;
    SELECT count(*) INTO live FROM c2c_rule_packs
     WHERE doc_type = e->>'doc_type' AND agency = e->>'agency' AND superseded_by IS NULL;
    IF live <> 1 THEN
      RAISE EXCEPTION '%:% must have exactly one live pack; found %', e->>'doc_type', e->>'agency', live;
    END IF;
  END LOOP;
END
$mig$;
